//! Small integer arithmetic helpers.
//!
//! The crate exposes two flavours of addition:
//!
//! * [`add`] — the plain operator, for call sites where overflow cannot occur
//!   or where a panic is the desired outcome.
//! * [`checked_add`] — the fallible form, for call sites that have to survive
//!   adversarial or user-supplied input.

/// Adds two [`i32`] values.
///
/// # Panics
///
/// Panics if the result overflows. Note that this is *debug-assertion*
/// behaviour: in a `--release` build without `overflow-checks` the same call
/// wraps around silently instead. If you cannot prove overflow impossible at
/// the call site, use [`checked_add`].
///
/// # Examples
///
/// ```
/// assert_eq!(target_lib::add(2, 3), 5);
/// ```
#[must_use]
#[inline]
pub fn add(a: i32, b: i32) -> i32 {
    a + b
}

/// Adds two [`i32`] values, returning `None` if the result overflows.
///
/// # Examples
///
/// ```
/// assert_eq!(target_lib::checked_add(2, 3), Some(5));
/// assert_eq!(target_lib::checked_add(i32::MAX, 1), None);
/// ```
#[must_use]
#[inline]
pub fn checked_add(a: i32, b: i32) -> Option<i32> {
    a.checked_add(b)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn add_sums_positive_operands() {
        assert_eq!(add(2, 3), 5);
    }

    #[test]
    fn add_is_commutative() {
        assert_eq!(add(2, 3), add(3, 2));
        assert_eq!(add(-7, 11), add(11, -7));
    }

    #[test]
    fn add_treats_zero_as_identity() {
        assert_eq!(add(0, 0), 0);
        assert_eq!(add(42, 0), 42);
        assert_eq!(add(0, -42), -42);
        assert_eq!(add(i32::MAX, 0), i32::MAX);
        assert_eq!(add(i32::MIN, 0), i32::MIN);
    }

    #[test]
    fn add_handles_negative_operands() {
        assert_eq!(add(-3, -4), -7);
        assert_eq!(add(-3, 4), 1);
        assert_eq!(add(i32::MIN + 1, -1), i32::MIN);
    }

    #[test]
    fn add_covers_full_range_without_overflow() {
        assert_eq!(add(i32::MAX - 1, 1), i32::MAX);
        assert_eq!(add(i32::MIN + 1, -1), i32::MIN);
        assert_eq!(add(i32::MIN, i32::MAX), -1);
    }

    #[test]
    fn checked_add_returns_some_when_in_range() {
        assert_eq!(checked_add(2, 3), Some(5));
        assert_eq!(checked_add(-2, -3), Some(-5));
        assert_eq!(checked_add(0, 0), Some(0));
        assert_eq!(checked_add(i32::MAX, 0), Some(i32::MAX));
        assert_eq!(checked_add(i32::MIN, 0), Some(i32::MIN));
    }

    #[test]
    fn checked_add_returns_none_on_positive_overflow() {
        assert_eq!(checked_add(i32::MAX, 1), None);
        assert_eq!(checked_add(i32::MAX, i32::MAX), None);
    }

    #[test]
    fn checked_add_returns_none_on_negative_overflow() {
        assert_eq!(checked_add(i32::MIN, -1), None);
        assert_eq!(checked_add(i32::MIN, i32::MIN), None);
    }

    #[test]
    fn checked_add_agrees_with_add_when_no_overflow() {
        for (a, b) in [(0, 0), (1, -1), (100, 200), (-100, -200), (i32::MIN, i32::MAX)] {
            assert_eq!(checked_add(a, b), Some(add(a, b)), "a={a}, b={b}");
        }
    }
}
